 * replaced the old, no-longer-updated material-icons library). Path data comes unchanged from
 * google/material-design-icons (Apache 2.0). Each icon is built once, the first time it's used.
 *
 * Generated; to add an icon, copy its 24 px SVG path from the same repo.
 */
object Symbols {

    private fun symbol(
        name: String,
        pathData: String,
        autoMirror: Boolean = false,
        viewport: Float = 960f,
        offsetY: Float = 960f
    ): ImageVector =
        ImageVector.Builder(
            name = "Symbols.$name",
            defaultWidth = 24.dp,
            defaultHeight = 24.dp,
            viewportWidth = viewport,
            viewportHeight = viewport,
            autoMirror = autoMirror
        )
            .addGroup(translationY = offsetY)
            .addPath(pathData = PathParser().parsePathString(pathData).toNodes(), fill = SolidColor(Color.Black))
            .clearGroup()
            .build()

